text.canStart:
function canStartTech343(n){
  if(!n||hasTech343(n.id)||(n.mutex&&(hasTech343(n.mutex)||tech343.act===n.mutex||tech343.prog[n.mutex]>0)))return false;
  if(n.pre&&n.pre.some(id=>!hasTech343(id)))return false;
  if(n.any&&n.any.length&&!n.any.some(id=>hasTech343(id)))return false;
  return !(n.minDone&&tech343.done.length<n.minDone);
}

text.start:
function startTech343(id){
  const n=TECH343_BY_ID[id];
  if(!canStartTech343(n))return false;
  if(tech343.act===id)return true;
  const fee=(diff===3||tech343.prog[n.id]>0)?0:n.cost;
  if(money<fee)return false;
  money-=fee;tech343.act=id;
  return true;
}

text.advance:
function advanceTech343(instituteN,universityN,techParkN,campusN,dataCenterN,megaProjectN,grandResearchN=0){
  techSpeed343=1+Math.min(7,instituteN+universityN+techParkN*2+campusN*2+dataCenterN+megaProjectN*2+grandResearchN*3)+tq('C6',1,0)+tq('D2',1,0)+tq('D5',2,0)+sq('edu',1,0);
  const n=TECH343_BY_ID[tech343.act];
  if(!n)return;
  const next=(tech343.prog[n.id]||0)+techSpeed343;
  if(next<n.points){tech343.prog[n.id]=next;return;}
  delete tech343.prog[n.id];tech343.done.push(n.id);tech343.act='';
  if(TECH_EDU343.includes(n.id))rebuildCov();
}

text.save:
function techSave343(){
  const prog={};
  for(const n of TECH343){const v=tech343.prog[n.id];if(Number.isInteger(v)&&v>0&&v<n.points)prog[n.id]=v;}
  if(!tech343.act&&!tech343.done.length&&!Object.keys(prog).length)return null;
  return{act:tech343.act,prog,done:tech343.done.slice()};
}

text.load:
function techLoad343(raw){
  const zero=emptyTech343();
  if(raw===undefined)return zero;
  if(!raw||typeof raw!=='object'||Array.isArray(raw)||typeof raw.act!=='string'||
     !raw.prog||typeof raw.prog!=='object'||Array.isArray(raw.prog)||!Array.isArray(raw.done))return zero;
  if(raw.act&&!TECH343_BY_ID[raw.act])return zero;
  const done=[],seen={};
  for(const id of raw.done){
    const n=TECH343_BY_ID[id];
    if(typeof id!=='string'||!n||seen[id]||(n.mutex&&seen[n.mutex]))return zero;
    seen[id]=1;done.push(id);
  }
  const prog={};
  for(const id of Object.keys(raw.prog)){
    const n=TECH343_BY_ID[id],v=raw.prog[id];
    if(!n||!Number.isInteger(v)||v<=0||v>=n.points||seen[id])return zero;
    prog[id]=v;
  }
  for(const id of Object.keys(prog)){const m=TECH343_BY_ID[id].mutex;if(m&&(seen[m]||prog[m]!==undefined||raw.act===m))return zero;}
  if(raw.act&&(seen[raw.act]||(TECH343_BY_ID[raw.act].mutex&&
     (seen[TECH343_BY_ID[raw.act].mutex]||prog[TECH343_BY_ID[raw.act].mutex]!==undefined))))return zero;
  return{act:raw.act,prog,done};
}

